        self._setup_control_panel(control_frame)

        # 좌하단: 실행 상태
        status_frame = ctk.CTkFrame(grid_frame, fg_color="transparent")
        status_frame.grid(row=1, column=0, sticky="nsew", padx=(0, 4), pady=(4, 0))
